import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class CodeforcesVariant2 {

    public static int findIndex(int target, int[] arr) {
        int start = 0;
        int end = arr.length - 1;
        while (start <= end) {
            int mid = (start + end) / 2;
            if (arr[mid] == target) return mid;
            if (target > arr[mid]) start = mid + 1;
            else end = mid - 1;
        }
        return -1;
    }

    public static void main(String[] args) throws IOException {
        InputStream inStream = System.in;
        BufferedReader br = new BufferedReader(new InputStreamReader(inStream));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int maxSegment = 0, totalW = 0;
        String line = br.readLine();
        char[] sequence = line.toCharArray();

        for (int i = 0; i < n; i++) {
            if (sequence[i] != '_' && sequence[i] != '(') {
                int segmentCount = 0;
                for (int j = i; j < n; j++) {
                    if (sequence[j] != '_' && sequence[j] != '(') segmentCount++;
                    if (sequence[j] == '_' || sequence[j] == '(' || j == n - 1) {
                        maxSegment = Math.max(maxSegment, segmentCount);
                        i = j;
                        break;
                    }
                }
            }
            if (sequence[i] == '(') {
                int count = 0;
                for (int j = i; j < n; j++) {
                    if ((sequence[j] == '_' || sequence[j] == ')') && count > 0) {
                        totalW++;
                        count = 0;
                    }
                    if (sequence[j] == ')') {
                        i = j;
                        break;
                    }
                    if (sequence[j] != '_' && sequence[j] != '(') count++;
                }
            }
        }
        System.out.println(maxSegment + " " + totalW);
    }
}
